import{_ as e,o as a,c as s,ao as i}from"./chunks/framework.8qRmdHEo.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"StrictMode.jl","text":"Loud guarantees for fast Julia","tagline":"Fast by default, and loud the moment you slip off it — not something you discover by profiling.","actions":[{"theme":"brand","text":"Getting Started","link":"/getting_started"},{"theme":"alt","text":"Guarantees","link":"/guarantees"},{"theme":"alt","text":"API Reference","link":"/api"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/el-oso/StrictMode.jl"}]},"features":[{"title":"Ask for the fast path","details":"Say what you want at a call site or a definition — this call must not allocate, this one must stay type-stable — and hear about it the moment it does not hold."},{"title":"Catch the silent traps","details":"Two packages. StrictMode reads inferred types and typed IR, and warns. Add StrictModeTest and AllocCheck, JET and TrimCheck prove the same properties and fail your build. Boxing and quietly allocating loops stop being invisible."},{"title":"Zero cost when disabled","details":"Checks sit behind a Preferences flag, on by default so dev and test need no setup. Turn it off for a shipped application and each macro compiles to the bare call."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),n={name:"index.md"};function l(o,t,r,h,d,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h2 id="Why" tabindex="-1">Why <a class="header-anchor" href="#Why" aria-label="Permalink to &quot;Why {#Why}&quot;">​</a></h2><p>Julia will let your code box a value, miss an inline, drift into a type instability, or allocate in a hot loop — without saying a word. You find out with a profiler, later. StrictMode lets you ask for those properties out loud, and hear about it the moment one breaks.</p><h3 id="Safety,-flexibility,-speed-—-all-three" tabindex="-1">Safety, flexibility, speed — all three <a class="header-anchor" href="#Safety,-flexibility,-speed-—-all-three" aria-label="Permalink to &quot;Safety, flexibility, speed — all three {#Safety,-flexibility,-speed-—-all-three}&quot;">​</a></h3><p>The position is a greedy one. Each of the usual approaches gives one of the three away:</p><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;">safety</th><th style="text-align:right;">flexibility</th><th style="text-align:right;">speed</th></tr></thead><tbody><tr><td style="text-align:right;">Julia, plain</td><td style="text-align:right;">by construction, for all code</td><td style="text-align:right;">full — generic code stays generic</td><td style="text-align:right;">leaks where a collector pauses, a specialization goes unstable, or a literal widens a kernel</td></tr><tr><td style="text-align:right;">Rust</td><td style="text-align:right;">in safe code</td><td style="text-align:right;">constrained — every program obeys the rules, needed or not</td><td style="text-align:right;">yes, until a kernel needs <code>unsafe</code>, and then the proof stops wholesale</td></tr><tr><td style="text-align:right;">Julia with StrictMode</td><td style="text-align:right;">unchanged</td><td style="text-align:right;">unchanged</td><td style="text-align:right;">the properties that cost speed are named, checked and gated</td></tr></tbody></table><p>Memory safety is never what is at stake here: in Julia it holds for all code, always. What leaks is speed, in a handful of specific and nameable ways — so a guarantee is something you opt into, for one property, one signature at a time, and it compiles away entirely in a shipped build.</p><p>To be plain about what that delivers: StrictMode does not make code fast. It makes the difference between the code you wrote and the code you got <em>visible</em>, per property, and fails a build when that difference appears. The <a href="/StrictMode.jl/v0.5/guarantees#Compared-with-Rust">comparison with Rust</a> works this through, including the two places Rust&#39;s model covers ground this one does not yet.</p><h2 id="Two-packages" tabindex="-1">Two packages <a class="header-anchor" href="#Two-packages" aria-label="Permalink to &quot;Two packages {#Two-packages}&quot;">​</a></h2><p>Know this first — it decides which macro you write.</p><p><strong><a href="./guarantees">StrictMode</a></strong> goes in your <code>Project.toml</code>. It reads inferred types and typed IR and needs no other package. Where it is <strong>guessing</strong> — the allocation and trim checks — it warns instead of failing your build; where it reads the compiled output, it throws.</p><p><strong><a href="./proof_tier">StrictModeTest</a></strong> goes in your <code>test/Project.toml</code>. It brings AllocCheck, JET and TrimCheck, and <strong>gates</strong>: a violation fails CI. Your users never install those backends just to use your package.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         write @assert_noalloc          write @test_noalloc</span></span>
<span class="line"><span>                  │                             │</span></span>
<span class="line"><span>              StrictMode                  StrictModeTest</span></span>
<span class="line"><span>           reads typed IR                asks AllocCheck</span></span>
<span class="line"><span>                  ↓                             ↓</span></span>
<span class="line"><span>              warns  ⚠                       throws  ✗</span></span>
<span class="line"><span>         while you iterate                   in your tests</span></span></code></pre></div><p>Two macros, two uses: one light enough to keep on while you edit, one strict enough to fail a test.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@assert_noalloc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> kernel!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, A, B)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># StrictMode: the scan — warns</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@test_noalloc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   kernel!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, A, B)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># StrictModeTest: AllocCheck&#39;s proof — throws</span></span></code></pre></div><blockquote><p>StrictMode grew out of a JuliaCon 2024 talk, <em>&quot;Why do we need a stricter Julia mode?&quot;</em> The traps that motivated it turned up while tuning a SIMD FFT, where indexing a tuple with a runtime value quietly boxed and cost a measured <strong>135× slowdown</strong> — the kind of thing you only ever find by profiling.</p></blockquote><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> StrictMode</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@assert_noalloc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># warns if the call looks like it allocates</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@assert_typestable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> muladd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># throws on an inconcrete return type</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@strict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            dot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(u, v)              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the guarantees a hot path wants, together</span></span></code></pre></div><p>From here you can follow <a href="./getting_started">Getting Started</a> for a walkthrough, read through the <a href="./guarantees">Guarantees</a> one by one, or skip to the <a href="./api">API Reference</a>.</p>`,17)])])}const k=e(n,[["render",l]]);export{g as __pageData,k as default};
